204	type RespHeaderOps struct {
205		*HeaderOps
206	
207		// If set, header operations will be deferred until
208		// they are written out and only performed if the
209		// response matches these criteria.
210		Require *caddyhttp.ResponseMatcher `json:"require,omitempty"`
211	
212		// If true, header operations will be deferred until
213		// they are written out. Superseded if Require is set.
214		// Usually you will need to set this to true if any
215		// fields are being deleted.
216		Deferred bool `json:"deferred,omitempty"`
217	}
