	buf.Reset()
	defer bufPool.Put(buf)

	repl := r.Context().Value(caddy.ReplacerCtxKey).(*caddy.Replacer)

	// matched indicates whether one of the configured response handlers
	// elected to intercept (and buffer) the final response; informational
	// 1xx responses never set this on their own because they pass through
	// the recorder regardless of the buffering decision
	matched := false

	rec := interceptedResponseHandler{replacer: repl}
	rec.ResponseRecorder = caddyhttp.NewResponseRecorder(w, buf, func(status int, header http.Header) bool {
		// see if any response handler is configured for this original response
		for i, rh := range ir.HandleResponse {
			if rh.Match != nil && !rh.Match.Match(status, header) {
				continue
			}
			rec.handler = rh
			rec.handlerIndex = i
			matched = true

			// a matching response handler always buffers the final
			// response so it can be replaced or modified before it is
			// written to the client
			return true
		}

		return false
	})

